import { expect, test, vi } from 'vitest';
import ThemeInfo from './ThemeInfo';

vi.mock('next/headers', () => ({
  cookies: async () => ({
    get: (name: string) => {
      if (name === 'theme') return { value: 'dark' };
      return undefined;
    },
  }),
  headers: async () => ({
    get: (name: string) => {
      if (name === 'accept-language') return 'en-US';
      return null;
    },
  }),
}));

test('ThemeInfo renders correctly with values', async () => {
  const result = await ThemeInfo();

  // result is a React Element (likely a div with children)
  // structure: <div><p>Current Theme: {theme}</p><p>Preferred Language: {lang}</p></div>
  // children is an array of 2 elements.

  const children = result.props.children;
  expect(children[0].props.children).toEqual(['Current Theme: ', 'dark']);
  expect(children[1].props.children).toEqual(['Preferred Language: ', 'en-US']);
});

